// Complete ISO 27001:2022 Clauses 4-10 with sub-clauses
export const iso27001Clauses = [
  {
    clause: "4",
    title: "Context of the Organization",
    subClauses: [
      { id: "4.1", title: "Understanding the organization and its context", description: "The organization shall determine external and internal issues that are relevant to its purpose and that affect its ability to achieve the intended outcome(s) of its information security management system.", expectedEvidence: "SWOT analysis, context documentation, stakeholder maps" },
      { id: "4.2", title: "Understanding the needs and expectations of interested parties", description: "The organization shall determine: interested parties that are relevant to the information security management system; the relevant requirements of these interested parties; which of these requirements will be addressed through the information security management system.", expectedEvidence: "SWOT analysis, context documentation, stakeholder maps" },
      { id: "4.3", title: "Determining the scope of the information security management system", description: "The organization shall determine the boundaries and applicability of the information security management system to establish its scope. When determining this scope, the organization shall consider: the external and internal issues referred to in understanding the organization and its context; the requirements referred to in understanding the needs and expectations of interested parties; interfaces and dependencies between activities performed by the organization, and those that are performed by other organizations. The scope shall be available as documented information.", expectedEvidence: "SWOT analysis, context documentation, stakeholder maps" },
      { id: "4.4", title: "Information security management system", description: "The organization shall establish, implement, maintain, and continually improve an information security management system, including the processes needed and their interactions, in accordance with the requirements of this international standard.", expectedEvidence: "SWOT analysis, context documentation, stakeholder maps" },
    ]
  },
  {
    clause: "5",
    title: "Leadership",
    subClauses: [
      { id: "5.1", title: "Leadership and commitment", description: "Top management shall demonstrate leadership and commitment to the information security management system (ISMS) by ensuring the policy and objectives align with the organization’s strategic direction; integrating ISMS requirements into processes; providing necessary resources; communicating the importance of information security; ensuring the ISMS achieves its intended outcomes; supporting personnel to enhance its effectiveness; promoting continual improvement; and enabling other management roles to demonstrate leadership in their areas.", expectedEvidence: "Management meeting records, policy document, role assignments" },
      { id: "5.2", title: "Policy", description: "Top management shall establish an information security policy that is appropriate to the organization’s purpose, includes information security objectives or provides a framework for setting them, commits to satisfying applicable information security requirements, and supports continual improvement of the information security management system (ISMS). The policy shall be documented, communicated within the organization, and made available to relevant interested parties, as appropriate.", expectedEvidence: "Management meeting records, policy document, role assignments" },
      { id: "5.3", title: "Organizational roles, responsibilities and authorities", description: "Top management shall ensure that roles related to information security have clearly defined, assigned, and communicated responsibilities and authorities within the organization, including ensuring the ISMS conforms to the requirements of this document and that its performance is reported to top management.", expectedEvidence: "Management meeting records, policy document, role assignments" },
    ]
  },
  {
    clause: "6",
    title: "Planning",
    subClauses: [
      { id: "6.1.1", title: "Actions to address risks and opportunities", description: "When planning the information security management system (ISMS), the organization shall consider internal and external issues, as well as the needs and expectations of interested parties, to identify risks and opportunities that must be addressed to ensure the ISMS achieves its intended outcomes, minimizes undesired effects, and promotes continual improvement. The organization shall also plan actions to address these risks and opportunities, integrate them into ISMS processes, and evaluate their effectiveness.", expectedEvidence: "Risk registers, risk assessment reports, treatment plans" },
      { id: "6.1.2", title: "Information security risk assessment", description: "The organization shall define and implement an information security risk assessment process with clear risk and acceptance criteria to ensure consistent and comparable results. It shall identify risks to the confidentiality, integrity, and availability of information, analyze their impact and likelihood, and evaluate them against established criteria to prioritize for treatment. Documented information on the risk assessment process shall be maintained.", expectedEvidence: "Risk registers, risk assessment reports, treatment plans" },
      { id: "6.1.3", title: "Information security risk treatment", description: "The organization shall establish and implement an information security risk treatment process to select suitable risk treatment options based on assessment results, determine and verify necessary controls, develop a risk treatment plan, and obtain risk owners’ approval and acceptance of residual risks. It shall also prepare a Statement of Applicability (SoA) listing the required controls, justification for their inclusion, implementation status, and reasons for excluding any Annex A controls.", expectedEvidence: "Risk registers, risk assessment reports, treatment plans" },
      { id: "6.2", title: "Information security objectives and planning to achieve them", description: "The organization shall establish information security objectives at relevant levels and functions, ensuring they align with the information security policy, are measurable where possible, reflect applicable requirements and risk results, and are monitored, communicated, updated, and documented. When planning to achieve these objectives, the organization shall define the actions to be taken, required resources, responsible personnel, completion timelines, and methods for evaluating results.", expectedEvidence: "Risk registers, risk assessment reports, treatment plans" },
      { id: "6.3", title: "Planning of changes", description: "When changes to the information security management system are required, the organization shall ensure they are implemented in a planned and controlled manner.", expectedEvidence: "Risk registers, risk assessment reports, treatment plans" },
    ]
  },
  {
    clause: "7",
    title: "Support",
    subClauses: [
      { id: "7.1", title: "Resources", description: "The organization shall identify and provide the necessary resources to establish, implement, maintain, and continually improve the information security management system.", expectedEvidence: "Training logs, communication records, document control logs" },
      { id: "7.2", title: "Competence", description: "The organization shall determine the required competence of individuals performing tasks that impact information security performance, ensure they are qualified through appropriate education, training, or experience, take necessary actions to develop required competence where needed, evaluate the effectiveness of those actions, and maintain documented evidence of competence.", expectedEvidence: "Training logs, communication records, document control logs" },
      { id: "7.3", title: "Awareness", description: "Individuals performing work under the organization’s control shall be aware of the information security policy, their role in contributing to the effectiveness of the ISMS, and the benefits of improved information security performance, as well as the consequences of not complying with ISMS requirements.", expectedEvidence: "Training logs, communication records, document control logs" },
      { id: "7.4", title: "Communication", description: "The organization shall identify the need for internal and external communications related to the information security management system, specifying what information to communicate, when, with whom, and how.", expectedEvidence: "Training logs, communication records, document control logs" },
      { id: "7.5.1", title: "Documented information – General", description: "The organization’s information security management system shall include all documented information required by this document, as well as any additional documentation deemed necessary by the organization to ensure the ISMS’s effectiveness.", expectedEvidence: "Training logs, communication records, document control logs" },
      { id: "7.5.2", title: "Creating and updating", description: "When creating or updating documented information, the organization shall ensure it is properly identified and described (e.g., title, date, author, reference number), appropriately formatted and recorded on suitable media (e.g., language, software version, graphics, paper, electronic), and reviewed and approved for suitability and adequacy.", expectedEvidence: "Training logs, communication records, document control logs" },
      { id: "7.5.3", title: "Control of documented information", description: "Documented information required by the ISMS and this document shall be controlled to ensure it is available and suitable for use when needed, and adequately protected from loss of confidentiality, improper use, or loss of integrity. Controls shall address distribution, access, retrieval, use, storage and preservation (including legibility), change management (e.g., version control), and retention and disposition. Documented information from external sources deemed necessary for ISMS planning and operation shall also be appropriately identified and controlled.", expectedEvidence: "Training logs, communication records, document control logs" },
    ]
  },
  {
    clause: "8",
    title: "Operation",
    subClauses: [
      { id: "8.1", title: "Operational planning and control", description: "The organization shall plan, implement, and control processes required to meet requirements and carry out actions from clause 6 by establishing process criteria and implementing controls accordingly. Documented information shall be maintained to provide confidence that processes are executed as planned. Planned changes shall be controlled, and the consequences of unintended changes reviewed, with actions taken to mitigate any adverse effects. Additionally, externally provided processes, products, or services relevant to the ISMS shall be properly controlled.", expectedEvidence: "Procedure documents, implementation records, risk logs" },
      { id: "8.2", title: "Information security risk assessment", description: "The organization shall conduct information security risk assessments at planned intervals or when significant changes occur or are proposed, following the criteria defined in its risk assessment process, and shall maintain documented information of the assessment results.", expectedEvidence: "Procedure documents, implementation records, risk logs" },
      { id: "8.3", title: "Information security risk treatment", description: "The organization shall implement its information security risk treatment plan and maintain documented information of the results.", expectedEvidence: "Procedure documents, implementation records, risk logs" },
    ]
  },
  {
    clause: "9",
    title: "Performance Evaluation",
    subClauses: [
      { id: "9.1", title: "Monitoring, measurement, analysis and evaluation", description: "The organization shall determine what information security processes and controls need to be monitored and measured, the methods to ensure valid, comparable, and reproducible results, the timing and responsible personnel for monitoring, measurement, analysis, and evaluation. Documented information shall be maintained as evidence, and the organization shall assess information security performance and the effectiveness of the ISMS.", expectedEvidence: "Audit reports, performance dashboards, review minutes" },
      { id: "9.2", title: "Internal audit", description: "The organization shall conduct internal audits at planned intervals to determine whether the information security management system conforms to the organization’s own ISMS requirements and the requirements of this document, and whether it is effectively implemented and maintained. The organization shall plan, establish, implement, and maintain an audit program specifying frequency, methods, responsibilities, planning requirements, and reporting, taking into account the importance of the processes and results of previous audits. Audit criteria and scope shall be defined for each audit, auditors shall be selected to ensure objectivity and impartiality, and audit results shall be reported to relevant management. Documented information shall be maintained as evidence of the audit program implementation and results.", expectedEvidence: "Audit reports, performance dashboards, review minutes" },
      { id: "9.3.1", title: "Management review – General", description: "Top management shall review the organization’s information security management system at planned intervals to ensure its ongoing suitability, adequacy, and effectiveness.", expectedEvidence: "Audit reports, performance dashboards, review minutes" },
      { id: "9.3.2", title: "Management review – Inputs", description: "The management review shall consider the status of actions from previous management reviews, changes in external and internal issues relevant to the information security management system, changes in the needs and expectations of interested parties relevant to the information security management system, feedback on information security performance including trends in nonconformities and corrective actions, monitoring and measurement results, audit results, and fulfilment of information security objectives, feedback from interested parties, results of risk assessments and the status of the risk treatment plan, and opportunities for continual improvement.", expectedEvidence: "Audit reports, performance dashboards, review minutes" },
      { id: "9.3.3", title: "Management review – Results", description: "The results of the management review shall include decisions regarding opportunities for continual improvement and any required changes to the information security management system, with documented information maintained as evidence of the review outcomes.", expectedEvidence: "Audit reports, performance dashboards, review minutes" },
    ]
  },
  {
    clause: "10",
    title: "Improvement",
    subClauses: [
      { id: "10.1", title: "Continual improvement", description: "The organization shall continually improve the suitability, adequacy, and effectiveness of the information security management system.", expectedEvidence: "Corrective action plans, improvement records, continuous improvement policy statements" },
      { id: "10.2", title: "Nonconformity and corrective action", description: "When a nonconformity occurs, the organization shall take action to control and correct it, address its consequences, eliminate its causes to prevent recurrence, implement required actions, review their effectiveness, and update the ISMS if necessary. Corrective actions shall be appropriate to the impact, and documented information shall be maintained as evidence of the nonconformity and actions taken.", expectedEvidence: "Risk Register, Corrective action plans, improvement records, continuous improvement policy statements" },
    ]
  },
];

// Complete ISO 27001:2022 Annex A Controls (sample subset - expand as needed)
export const annexAControls = [
  // --- ORGANIZATIONAL CONTROLS (A.5: 37 controls) ---
  { id: "A.5.1", title: "Policies for information security", description: "Define, approve, publish, and regularly review a set of high-level and topic-specific information security policies. These must be communicated to and acknowledged by all relevant personnel and interested parties to establish a clear security framework.", domain: "Organizational Controls", expectedEvidence: "Master list of Information Security Policies., Approved Information Security Policy Documents"},
  { id: "A.5.2", title: "Information security roles and responsibilities", description: "Clearly define and allocate all information security roles and responsibilities throughout the organization. This ensures full accountability and makes sure that security tasks are tailored to the organization's specific needs.", domain: "Organizational Controls", expectedEvidence: "List of roles and responsibilities for information security., Role descriptions that include specific duties and tasks." },
  { id: "A.5.3", title: "Segregation of duties", description: "Implement segregation of duties by separating conflicting roles and responsibilities. This is a key control to prevent a single person from having the ability to commit fraud, bypass security, or make an error without detection.", domain: "Organizational Controls", expectedEvidence: "Documented roles and responsibilities showing segregation of conflicting duties., Access control policies or documentation reflecting segregation of duties." },
  { id: "A.5.4", title: "Management responsibilities", description: "Ensure that management actively requires all personnel and relevant parties to apply information security in line with the organization's established policies and procedures, demonstrating leadership and commitment from the top.", domain: "Organizational Controls", expectedEvidence: "Information security roles and responsibilities included in job descriptions of employees" },
  { id: "A.5.5", title: "Contact with authorities", description: "Establish and maintain active contact with relevant authorities, such as regulatory bodies, data protection agencies, or law enforcement, to ensure timely communication and support for information security, legal, and compliance matters.", domain: "Organizational Controls", expectedEvidence: "List of relevant authorities, including contact details, responsibilities, and roles." },
  { id: "A.5.6", title: "Contact with special interest groups", description: "Establish and maintain contact with special interest groups, security forums, and professional associations. This allows the organization to stay updated on the latest threats, best practices, and security innovations.", domain: "Organizational Controls", expectedEvidence: "List of identified special interest groups and associations, including memberships, event participation, and communication channels." },
  { id: "A.5.7", title: "Threat intelligence", description: "Proactively collect and analyze information related to information security threats. This process is used to produce actionable threat intelligence, which informs and improves defensive strategies, risk management, and incident response.", domain: "Organizational Controls", expectedEvidence: "Threat Intelligence Policy" },
  { id: "A.5.8", title: "Information security in project management", description: "Integrate information security considerations, risk assessments, and control requirements into all phases of the project management lifecycle. This ensures that security is addressed from the project's inception to its completion.", domain: "Organizational Controls", expectedEvidence: "Project plans that include clear security objectives and risk assessments., Project Impact Analysis document" },
  { id: "A.5.9", title: "Inventory of information and other associated assets", description: "Develop and maintain a comprehensive inventory of all information and associated assets (e.g., hardware, software, services, data). This inventory must include assigned owners to ensure accountability for each asset.", domain: "Organizational Controls", expectedEvidence: "Information Asset Management Policy, Documented Asset Inventory" },
  { id: "A.5.10", title: "Acceptable use of information and other associated assets", description: "Define, document, and implement clear rules for the acceptable use of the organization's information and assets. These rules must be communicated to all users to prevent misuse and protect assets.", domain: "Organizational Controls", expectedEvidence: "Acceptable Use Policy clearly defining rules for the use of information and information assets" },
  { id: "A.5.11", title: "Return of assets", description: "Establish a formal process to ensure that all personnel and interested parties return all of the organization’s assets in their possession upon the change or termination of their employment, contract, or agreement.", domain: "Organizational Controls", expectedEvidence: "Asset return policy" },
  { id: "A.5.12", title: "Classification of information", description: "Classify all information based on its security needs (confidentiality, integrity, availability) and its importance to the organization. This classification guides how the information is handled and protected.", domain: "Organizational Controls", expectedEvidence: "Information Classification Policy" },
  { id: "A.5.13", title: "Labelling of information", description: "Develop and implement a set of procedures for labelling information according to its classification. This applies to both digital and physical assets, ensuring handlers are aware of its sensitivity.", domain: "Organizational Controls", expectedEvidence: "Information Labelling Policy and Procedures" },
  { id: "A.5.14", title: "Information transfer", description: "Establish and enforce rules, procedures, or formal agreements for all types of information transfer facilities, both within the organization and with external parties, to protect data from being compromised in transit.", domain: "Organizational Controls", expectedEvidence: "Data Sharing Policy, Agreements with thirdparty" },
  { id: "A.5.15", title: "Access control", description: "Establish, document, and implement rules to control both physical and logical access to information and other assets. Access rights must be based on business and information security requirements (e.g., least privilege).", domain: "Organizational Controls", expectedEvidence: "Access Control Policy" },
  { id: "A.5.16", title: "Identity management", description: "Manage the full lifecycle of digital and physical identities, from creation (onboarding) through to modification (role changes) and deletion (offboarding), to ensure access is always appropriate.", domain: "Organizational Controls", expectedEvidence: "Identity Management Policy statements" },
  { id: "A.5.17", title: "Authentication information", description: "Control the allocation and management of all authentication information (like passwords, keys, or tokens) through a formal process. This includes advising personnel on how to securely handle their credentials.", domain: "Organizational Controls", expectedEvidence: "Authentication Information Management Policy statements" },
  { id: "A.5.18", title: "Access rights", description: "Ensure that access rights to information and assets are formally provisioned, reviewed, modified, and removed according to the organization's access control policy. This process ensures the principle of least privilege is maintained.", domain: "Organizational Controls", expectedEvidence: "Access Control Policy" },
  { id: "A.5.19", title: "Information security in supplier relationships", description: "Define and implement processes to manage the information security risks associated with using a supplier's products or services. This includes due diligence before and during the relationship.", domain: "Organizational Controls", expectedEvidence: "Supplier Risk Management Policy" },
  { id: "A.5.20", title: "Addressing information security within supplier agreements", description: "Establish and formally agree upon all relevant information security requirements with each supplier. These requirements should be documented in binding contracts and tailored to the type of supplier relationship.", domain: "Organizational Controls", expectedEvidence: "Supplier Risk Management Policy" },
  { id: "A.5.21", title: "Managing information security in the information and communication technology (ict) supply chain", description: "Define and implement processes to manage the specific information security risks associated with the ICT (Information and Communication Technology) products and services supply chain, protecting against tampering or compromise.", domain: "Organizational Controls", expectedEvidence: "ICT Supply Chain Risk Management Policy" },
  { id: "A.5.22", title: "Monitoring, review and change management of supplier services", description: "Regularly monitor, review, and evaluate supplier information security practices and service delivery. A formal process must also be in place to manage any changes in supplier services that could impact security.", domain: "Organizational Controls", expectedEvidence: "Supplier Risk Management Policy" },
  { id: "A.5.23", title: "Information security for use of cloud services", description: "Establish and implement formal processes for the acquisition, use, management, and exit from cloud services. These processes must align with the organization's specific information security requirements.", domain: "Organizational Controls", expectedEvidence: "Cloud Service Management Policy and Procedures" },
  { id: "A.5.24", title: "Information security incident management planning and preparation", description: "Plan and prepare for managing information security incidents by defining, establishing, and communicating the necessary processes, roles, and responsibilities to all relevant stakeholders.", domain: "Organizational Controls", expectedEvidence: "Information Security Roles and Responsibilities, Information Security Incident Management Policy and Procedures" },
  { id: "A.5.25", title: "Assessment and decision on information security events", description: "Establish a consistent process to assess all information security events (e.g., alerts, user reports). This process must include criteria to decide if an event should be escalated and categorized as an information security incident.", domain: "Organizational Controls", expectedEvidence: "Incident Response Plan with documented procedure for assessing and catehorizing events" },
  { id: "A.5.26", title: "Response to information security incidents", description: "Ensure that all information security incidents are responded to in accordance with documented procedures. This includes containment, investigation, and remediation actions to minimize impact.", domain: "Organizational Controls", expectedEvidence: "Incident Response Plan with documented procedure for responding to security incidents" },
  { id: "A.5.27", title: "Learning from information security incidents", description: "Use the knowledge gained from analyzing information security incidents to strengthen and improve the organization's security controls, policies, and incident management processes, preventing future recurrence.", domain: "Organizational Controls", expectedEvidence: "Documented updates to security procedures and controls that were made based on incident knowledge." },
  { id: "A.5.28", title: "Collection of evidence", description: "Establish and implement formal procedures for the identification, collection, acquisition, and preservation of evidence related to information security events, ensuring it is admissible for legal or disciplinary actions.", domain: "Organizational Controls", expectedEvidence: "Documented procedures for identifying, collecting, acquiring, and preserving evidence." },
  { id: "A.5.29", title: "Information security during disruption", description: "Plan and implement measures to maintain information security at an appropriate and predefined level during any business disruption (e.g., crisis, disaster, or major outage).", domain: "Organizational Controls", expectedEvidence: "Business continuity and disaster recovery plans that explicitly address information security during disruptions., Documentation of roles and responsibilities during disruptions, ensuring that personnel are clear on their tasks during emergencies." },
  { id: "A.5.30", title: "ICT readiness for business continuity", description: "Plan, implement, maintain, and test the readiness of your Information and Communication Technology (ICT) to ensure it can support business continuity objectives and requirements during a disruption.", domain: "Organizational Controls", expectedEvidence: "Documented Business continuity plan that outlines how ICT systems will support business continuity., Business Impact Analysis Methodology" },
  { id: "A.5.31", title: "Legal, statutory, regulatory and contractual requirements", description: "Identify, document, and keep up-to-date all relevant legal, statutory, regulatory, and contractual requirements related to information security. The organization must also define its approach to meet these requirements.", domain: "Organizational Controls", expectedEvidence: "Compliance Policy outlining legal, statutory, regulatory and contractual requirements" },
  { id: "A.5.32", title: "Intellectual property rights", description: "Implement appropriate procedures to identify, manage, and protect all intellectual property (IP) rights that the organization holds or is required to protect, in line with legal and contractual obligations.", domain: "Organizational Controls", expectedEvidence: "Documented policy and procedures for protecting intellectual property" },
  { id: "A.5.33", title: "Protection of records", description: "Ensure all organizational records (e.g., financial, legal, audit) are protected from loss, destruction, falsification, unauthorized access, and unauthorized release, in accordance with their classification and retention requirements.", domain: "Organizational Controls", expectedEvidence: "" },
  { id: "A.5.34", title: "Privacy and protection of personal identifiable information (PII)", description: "Identify and meet all requirements regarding the preservation of privacy and the protection of Personally Identifiable Information (PII). This must be done in accordance with applicable privacy laws, regulations, and contracts.", domain: "Organizational Controls", expectedEvidence: "Personally Identifiable Information Policy" },
  { id: "A.5.35", title: "Independent review of information security", description: "Ensure the organization’s approach to managing information security (including its policies, processes, and controls) is reviewed independently at planned intervals or when significant changes occur. This review provides an objective assessment of effectiveness.", domain: "Organizational Controls", expectedEvidence: "Review schedules showing planned and actual independent reviews." },
  { id: "A.5.36", title: "Compliance with policies, rules and standards for information security", description: "Regularly review the organization's compliance with its own information security policies, rules, and standards. This ensures that security practices are being followed correctly and consistently.", domain: "Organizational Controls", expectedEvidence: "Compliance Policy, Internal Audit Policy and Procedure" },
  { id: "A.5.37", title: "Documented operating procedures", description: "Ensure that clear, documented operating procedures for all information processing facilities (e.g., data centers, servers) are created and made available to the personnel who need them to perform their jobs.", domain: "Organizational Controls", expectedEvidence: "Documented SOPs for information processing facilities." },

  // --- PEOPLE CONTROLS (A.6: 8 controls) ---
  { id: "A.6.1", title: "Screening", description: "Conduct background verification checks on all candidates before they join, and perform ongoing screening for personnel in sensitive roles. All checks must be proportional to the role's risk and comply with all relevant laws and ethics.", domain: "People Controls", expectedEvidence: "Background verification policy outlining screening requirements." },
  { id: "A.6.2", title: "Terms and conditions of employment", description: "Ensure that all employment contracts and agreements explicitly state the information security responsibilities of both the personnel and the organization. This creates a formal, legal basis for security obligations.", domain: "People Controls", expectedEvidence: "Policy documents outlining employment contracts and confidentiality agreements to be signed before joining the organization, Policy documents outlining disciplinary actions for security breaches." },
  { id: "A.6.3", title: "Information security awareness, education and training", description: "Provide all personnel and relevant contractors with appropriate and regular information security awareness, education, and training. This must include updates on policies and procedures relevant to their job function.", domain: "People Controls", expectedEvidence: "Security awareness training plan and schedule." },
  { id: "A.6.4", title: "Disciplinary process", description: "Establish and communicate a formal disciplinary process to take appropriate action against personnel or other parties who have committed an information security policy violation. This ensures fair and consistent enforcement.", domain: "People Controls", expectedEvidence: "Documented disciplinary policy detailing violations and actions." },
  { id: "A.6.5", title: "Responsibilities after termination or change of employment", description: "Define, communicate, and enforce all information security responsibilities and duties that remain valid *after* an individual's employment or contract has been terminated or changed (e.g., non-disclosure agreements).", domain: "People Controls", expectedEvidence: "Policy documents outlining post-employment responsibilities, Employment contracts and NDAs defining post-employment security duties." },
  { id: "A.6.6", title: "Confidentiality or non-disclosure agreements", description: "Identify the organization's needs for protecting confidential information and use legally binding confidentiality or non-disclosure agreements (NDAs). These must be signed by personnel and other relevant parties and reviewed regularly.", domain: "People Controls", expectedEvidence: "Policy or procedure defining NDA use, enforcement, and review cycles." },
  { id: "A.6.7", title: "Remote working", description: "Implement and enforce specific security measures (technical, physical, and procedural) to protect information that is accessed, processed, or stored by personnel working remotely, ensuring security outside the organization's premises.", domain: "People Controls", expectedEvidence: "Policy outlining the security measures to be adopted while working remotely" },
  { id: "A.6.8", title: "Information security event reporting", description: "Provide a clear, simple, and timely mechanism for all personnel to report any observed or suspected information security events through appropriate channels, ensuring that incidents are identified and handled quickly.", domain: "People Controls", expectedEvidence: "Documented information security event reporting procedures" },

  // --- PHYSICAL CONTROLS (A.7: 14 controls) ---
  { id: "A.7.1", title: "Physical security perimeters", description: "Define and use clear physical security perimeters (like walls, fences, and secured entry points) to protect buildings and areas that contain sensitive information and critical assets from unauthorized physical access.", domain: "Physical Controls", expectedEvidence: "Documented security perimeters, including physical and logical boundaries." },
  { id: "A.7.2", title: "Physical entry", description: "Protect all secure areas with appropriate entry controls and access points (e.g., reception desks, key card systems, locked doors) to ensure that only authorized individuals can gain entry.", domain: "Physical Controls", expectedEvidence: "Documented entry control policy and procedures for each secure area." },
  { id: "A.7.3", title: "Securing offices, rooms and facilities", description: "Design and implement appropriate physical security measures for offices, rooms, and other facilities (e.g., locks, access controls) to protect them from unauthorized access, damage, and interference.", domain: "Physical Controls", expectedEvidence: "Documented physical security measures (e.g., access controls, barriers, monitoring systems)." },
  { id: "A.7.4", title: "Physical security monitoring", description: "Continuously monitor the organization's premises (e.g., using guards, CCTV, or alarm systems) to detect and respond to any unauthorized physical access attempts in a timely manner.", domain: "Physical Controls", expectedEvidence: "Document outlining continuous monitoring of the premises" },
  { id: "A.7.5", title: "Protecting against physical and environmental threats", description: "Design and implement protections against physical and environmental threats, such as natural disasters (fire, flood), malicious damage, or utility failures, to safeguard infrastructure and assets.", domain: "Physical Controls", expectedEvidence: "Disaster recovery plans and business continuity plans that include physical protection strategies." },
  { id: "A.7.6", title: "Working in secure areas", description: "Design and implement specific security measures and procedures for personnel working in designated secure areas (e.g., data centers) to protect the sensitive assets and information within them.", domain: "Physical Controls", expectedEvidence: "Access control policies and procedures specific to secure areas." },
  { id: "A.7.7", title: "Clear desk and clear screen", description: "Define and enforce clear desk policies for physical papers and removable media (e.g., locking them away) and clear screen policies for all devices (e.g., locking screens when unattended) to prevent unauthorized information access.", domain: "Physical Controls", expectedEvidence: "Clear Desk and Clear Screen Policy document with defined rules and enforcement measures." },
  { id: "A.7.8", title: "Equipment siting and protection", description: "Securely locate and protect all equipment to reduce risks from environmental threats (e.g., fire, water) and unauthorized access or damage, ensuring its continued availability and integrity.", domain: "Physical Controls", expectedEvidence: "Equipment security policies and procedures." },
  { id: "A.7.9", title: "Security of assets off-premises", description: "Implement specific security controls to protect all organizational assets (e.g., laptops, mobile devices) when they are used, stored, or transported off-site, mitigating risks like theft or loss.", domain: "Physical Controls", expectedEvidence: "Off-site asset policy, Asset declaration form" },
  { id: "A.7.10", title: "Storage media", description: "Manage all storage media (e.g., hard drives, USBs, backup tapes) throughout their entire lifecycle—from acquisition and use to transportation and final disposal—in accordance with the organization's classification and handling requirements.", domain: "Physical Controls", expectedEvidence: "Policy outlining storage media security, Asset disposal policy, Asset disposal form" },
  { id: "A.7.11", title: "Supporting utilities", description: "Protect all critical information processing facilities from power failures and other disruptions caused by failures in supporting utilities (e.g., electricity, HVAC, internet) using measures like UPS or backup generators.", domain: "Physical Controls", expectedEvidence: "Policy document outlining power and utility backups, Disaster recovery and business continuity plans." },
  { id: "A.7.12", title: "Cabling security", description: "Protect all cables that carry power, data, or supporting information services from interception, interference, or physical damage by using appropriate measures (e.g., conduits, secure routing, access restrictions).", domain: "Physical Controls", expectedEvidence: "Policy document outlining protection of cables" },
  { id: "A.7.13", title: "Equipment maintenance", description: "Perform correct and regular maintenance on all equipment to ensure the continued availability, integrity, and confidentiality of the information it processes or stores.", domain: "Physical Controls", expectedEvidence: "Policy outlining maintenance of equipments" },
  { id: "A.7.14", title: "Secure disposal or re-use of equipment", description: "Verify that all items of equipment containing storage media have had any sensitive data and licensed software securely removed or overwritten (e.g., sanitization, physical destruction) *before* they are disposed of or re-used.", domain: "Physical Controls", expectedEvidence: "Data sanitization policy and procedures for handling storage media." },

  // --- TECHNOLOGICAL CONTROLS (A.8: 34 controls) ---
  { id: "A.8.1", title: "User end point devices", description: "Protect all information that is stored on, processed by, or accessible from user endpoint devices (like laptops, smartphones, and tablets). This includes measures like encryption, anti-malware, and remote wipe capabilities.", domain: "Technological Controls", expectedEvidence: "Endpoint protection policy with clear guidelines on device security." },
  { id: "A.8.2", title: "Privileged access rights", description: "Strictly restrict and manage the allocation and use of all privileged access rights (e.g., 'admin' or 'root' accounts). This is critical for preventing misuse and limiting the impact of a potential compromise.", domain: "Technological Controls", expectedEvidence: "Privileged access control policy that defines how privileges are allocated, monitored, and reviewed." },
  { id: "A.8.3", title: "Information access restriction", description: "Restrict access to information and other associated assets (e.g., systems, applications) in accordance with the organization's established access control policy, enforcing principles like 'need-to-know'.", domain: "Technological Controls", expectedEvidence: "Access control policy document, outlining the principles, processes, and procedures for restricting access to sensitive information." },
  { id: "A.8.4", title: "Access to source code", description: "Appropriately manage and control both read and write access to all source code, development tools, and software libraries to prevent unauthorized viewing, copying, or modification and to protect intellectual property.", domain: "Technological Controls", expectedEvidence: "Access control policy that defines the access levels for source code, development tools, and software libraries., Documentation of access procedures, detailing how access is granted, revoked, and monitored for source code and development tools." },
  { id: "A.8.5", title: "Secure authentication", description: "Implement secure authentication technologies and procedures (e.g., Multi-Factor Authentication, strong password policies) based on the organization's access control policy and the sensitivity of the information being accessed.", domain: "Technological Controls", expectedEvidence: "Authentication policy that specifies the required methods, such as MFA or biometrics, and defines password policies., Access control policy that outlines user roles and permissions, and how authentication methods are aligned with these roles." },
  { id: "A.8.6", title: "Capacity management", description: "Monitor the use of all critical resources (e.g., CPU, storage, bandwidth) and adjust their capacity in line with current and expected future requirements. This prevents performance degradation and service outages.", domain: "Technological Controls", expectedEvidence: "Documentation of capacity planning processes that outline how resource requirements are forecasted and adjusted., Resource optimization strategies that show proactive efforts to reduce wastage and optimize usage." },
  { id: "A.8.7", title: "Protection against malware", description: "Implement comprehensive protection against malware (e.g., antivirus, web filtering, endpoint detection) and support this technology with appropriate user awareness training to prevent, detect, and remediate threats.", domain: "Technological Controls", expectedEvidence: "Anti-malware policy documenting the use of anti-malware softwares to protect company assets and data, Incident response plans, including documentation of malware-related incident handling, from detection to remediation." },
  { id: "A.8.8", title: "Management of technical vulnerabilities", description: "Obtain timely information about technical vulnerabilities in systems, evaluate the organization's exposure to them, and take appropriate measures (e.g., patching, configuration changes) to address the associated risk.", domain: "Technological Controls", expectedEvidence: "Risk assessments documenting the evaluation of identified vulnerabilities and the impact of exposure." },
  { id: "A.8.9", title: "Configuration management", description: "Establish, document, and maintain secure configuration baselines for all hardware, software, services, and networks. These configurations must be actively implemented, monitored for drift, and regularly reviewed.", domain: "Technological Controls", expectedEvidence: "Configuration management documentation that includes configuration baselines, standards, and guidelines." },
  { id: "A.8.10", title: "Information deletion", description: "Securely delete information stored in systems, devices, or any other storage media when it is no longer required by law, regulation, or business needs. This minimizes data exposure and reduces storage costs.", domain: "Technological Controls", expectedEvidence: "Data retention and deletion policy that specifies retention periods, deletion methods, and applicable legal or regulatory requirements." },
  { id: "A.8.11", title: "Data masking", description: "Use data masking techniques (e.g., anonymization, pseudonymization) to limit the exposure of sensitive information (especially PII) in non-production environments like testing and development, in line with policies and legal requirements.", domain: "Technological Controls", expectedEvidence: "Data masking policy outlining the process, scope, and implementation procedures., Documentation of sensitive data classifications that detail which types of data should be masked." },
  { id: "A.8.12", title: "Data leakage prevention", description: "Apply technical data leakage prevention (DLP) measures to systems, networks, and endpoint devices that handle sensitive information. These controls are designed to detect and prevent the unauthorized transfer or exfiltration of data.", domain: "Technological Controls", expectedEvidence: "DLP software and configurations documentation, Encryption protocols and access control policies for sensitive data." },
  { id: "A.8.13", title: "Information backup", description: "Maintain regular backup copies of all critical information, software, and systems. These backups must also be regularly tested for restore functionality in accordance with a formal backup policy.", domain: "Technological Controls", expectedEvidence: "Backup policy documentation that aligns with the organization’s information security and business continuity needs." },
  { id: "A.8.14", title: "Redundancy of information processing facilities", description: "Implement sufficient redundancy for all critical information processing facilities (e.g., servers, network links, power) to ensure they can meet the organization's availability requirements, even in the event of a component failure.", domain: "Technological Controls", expectedEvidence: "Business continuity plan that integrates redundancy strategies for ensuring availability during disruptions." },
  { id: "A.8.15", title: "Logging", description: "Produce, store, and protect logs that record activities, exceptions, faults, and other relevant events. These logs must be retained and analyzed to detect security incidents and support investigations.", domain: "Technological Controls", expectedEvidence: "Logging and monitoring policy, Log storage and retention policies that outline where logs are stored, how they are protected, and retention periods., Automated log analysis tools such as SIEM, including evidence of their deployment plans and configuration." },
  { id: "A.8.16", title: "Monitoring activities", description: "Monitor all networks, systems, and applications for anomalous behavior. When anomalies are detected, take appropriate actions to evaluate them as potential information security incidents.", domain: "Technological Controls", expectedEvidence: "Logging and monitoring policy, Monitoring tool configurations showing which networks, systems, and applications are being monitored." },
  { id: "A.8.17", title: "Clock synchronization", description: "Ensure that the clocks of all relevant information processing systems (e.g., servers, network devices) are synchronized to an approved and accurate time source. This is essential for correlating logs and investigating incidents.", domain: "Technological Controls", expectedEvidence: "Policies and procedures documenting how time synchronization is managed, including the steps for selecting time sources and maintaining synchronization." },
  { id: "A.8.18", title: "Use of privileged utility programs", description: "Restrict and tightly control the use of any utility programs that have privileged access and are capable of overriding system or application controls (e.g., debuggers, disk editors) to prevent misuse.", domain: "Technological Controls", expectedEvidence: "Access control policies and procedures defining how utility programs are restricted, including role-based access controls and approval processes." },
  { id: "A.8.19", title: "Installation of software on operational systems", description: "Implement formal procedures and technical measures to securely manage the installation of all software (including updates and patches) on operational systems, preventing the introduction of unauthorized or malicious code.", domain: "Technological Controls", expectedEvidence: "Software installation policy or documented procedures detailing the process for installing software securely." },
  { id: "A.8.20", title: "Networks security", description: "Secure, manage, and control all networks and network devices (e.g., routers, firewalls) to protect the information being transmitted and to safeguard connected systems and applications from network-based threats.", domain: "Technological Controls", expectedEvidence: "Network security policy detailing access controls, encryption standards, and device security., Network segmentation diagrams showing separation of internal, external, and guest networks." },
  { id: "A.8.21", title: "Security of network services", description: "Identify, implement, and monitor the security mechanisms, service levels, and service requirements for all network services (e.g., DNS, DHCP, VPNs), whether they are provided in-house or by a supplier.", domain: "Technological Controls", expectedEvidence: "Network security policies covering service security, monitoring, and compliance." },
  { id: "A.8.22", title: "Segregation of networks", description: "Segregate groups of information services, users, and information systems within the organization’s networks (e.g., using VLANs or firewalls). This helps prevent lateral movement by attackers and contains the impact of a breach.", domain: "Technological Controls", expectedEvidence: "Network architecture diagrams showing segmentation of information services, users, and systems., Policies and procedures for network segregation." },
  { id: "A.8.23", title: "Web filtering", description: "Manage and control access to external websites through web filtering technologies. This is done to reduce the organization's exposure to malicious content, malware, phishing sites, and other web-based threats.", domain: "Technological Controls", expectedEvidence: "Web filtering policy & procedures defining restricted and allowed website categories." },
  { id: "A.8.24", title: "Use of cryptography", description: "Define and implement formal rules for the effective use of cryptography, including the management of cryptographic keys throughout their lifecycle (generation, storage, rotation, destruction), to protect data confidentiality and integrity.", domain: "Technological Controls", expectedEvidence: "Cryptographic policy & procedures defining encryption requirements." },
  { id: "A.8.25", title: "Secure development life cycle", description: "Establish and apply rules for the secure development of software and systems throughout the entire development life cycle (SDLC). This ensures security is built in from the beginning, not added as an afterthought.", domain: "Technological Controls", expectedEvidence: "Secure development policy & procedures outlining security requirements." },
  { id: "A.8.26", title: "Application security requirements", description: "Ensure that information security requirements are identified, specified, and formally approved when any new application is being developed or acquired. These requirements must be met before the application goes live.", domain: "Technological Controls", expectedEvidence: "Documented security requirements for new applications., Risk assessment reports identifying security needs." },
  { id: "A.8.27", title: "Secure system architecture and engineering principles", description: "Establish, document, and maintain a set of principles for engineering secure systems. These principles must be applied to all information system development, integration, and architecture activities.", domain: "Technological Controls", expectedEvidence: "Documented secure engineering principles and policies., Security design documentation for developed systems." },
  { id: "A.8.28", title: "Secure coding", description: "Apply formal secure coding principles to all software development to prevent common vulnerabilities (e.g., SQL injection, XSS). This includes training developers and reviewing code for security flaws.", domain: "Technological Controls", expectedEvidence: "Documented secure coding guidelines and best practices." },
  { id: "A.8.29", title: "Security testing in development and acceptance", description: "Define and implement formal security testing processes (e.g., SAST, DAST, penetration testing) within the development life cycle. This verifies that security requirements have been met before systems are moved to production.", domain: "Technological Controls", expectedEvidence: "Documented security testing processes and policies." },
  { id: "A.8.30", title: "Outsourced development", description: "Direct, monitor, and review all activities related to system development that has been outsourced to a third party. This ensures the supplier adheres to the organization's secure development and security standards.", domain: "Technological Controls", expectedEvidence: "Policies for managing third-party security risks." },
  { id: "A.8.31", title: "Separation of development, test and production environments", description: "Separate and secure the development, testing, and production environments. This prevents unauthorized access or changes to production systems and protects live data from being exposed in non-production environments.", domain: "Technological Controls", expectedEvidence: "Network architecture diagrams showing environment separation., Access control policies and role-based access configurations." },
  { id: "A.8.32", title: "Change management", description: "Ensure that all changes to information processing facilities and information systems are subject to a formal change management procedure. This includes assessing, approving, testing, and logging all changes to minimize risk.", domain: "Technological Controls", expectedEvidence: "Change management policy and procedures., Risk assessments and impact analyses for changes." },
  { id: "A.8.33", title: "Test information", description: "Appropriately select, protect, and manage any information used for testing. Sensitive production data should not be used in test environments unless it has been properly masked or anonymized.", domain: "Technological Controls", expectedEvidence: "Software Development Lifecycle, Test information guidelines" },
  { id: "A.8.34", title: "Protection of information systems during audit testing", description: "Ensure that any audit tests or assurance activities on operational (production) systems are carefully planned and formally agreed upon with appropriate management. This prevents accidental disruptions and ensures the audit is effective.", domain: "Technological Controls", expectedEvidence: "Formal audit plan, including scope, objectives, and methodologies., Documented agreements between the audit team and management." }
];


